import assert from 'node:assert/strict';
import SuperJSON from './dist/index.js';
const s = new SuperJSON({errorStack:{mode:'frames',includeCauses:'deep',sanitizeMessage:true}}); s.allowErrorProps('stackFrames'); const e = new Error('email a@b.com',{cause:new Error('url https://example.com')}); e.stack='Error: email a@b.com\n    at /tmp/example.js:1:2'; const r=s.serialize(e); console.log(JSON.stringify(r)); assert.equal(r.meta.values[0],'Error/frames'); const out=s.parse(s.stringify(e)); assert.equal(out.stack,'Error: email a@b.com\nat /tmp/example.js:1:2'); assert.equal(out.cause.message,'url [redacted]');
EOF
